#!/usr/bin/env python3
"""Generate evidence-first hardware compatibility and purchase pages."""
from pathlib import Path
from html import escape
import json

DOMAIN='https://aitoolsessentials.com'

def esc(x): return escape(str(x), quote=True)
def link_items(items): return ''.join(f'<li><a href="{esc(u)}" target="_blank" rel="external noopener">{esc(n)} ↗</a></li>' for n,u in items)
def card(h, body): return f'<section class="hardware-card"><h2>{h}</h2>{body}</section>'

def detail(h):
    fit=''.join(f'<tr><th>{esc(k)}</th><td>{esc(v)}</td></tr>' for k,v in h['service_fit'].items())
    unresolved=''.join(f'<li>{esc(x)}</li>' for x in h['unresolved'])
    specs=''.join(f'<li><strong>{esc(k)}:</strong> {esc(h[k])}</li>' for k in ['memory','storage','os','thermal'])
    schema=json.dumps({'@context':'https://schema.org','@type':'Product','name':h['name'],'brand':{'@type':'Brand','name':h['vendor']},'url':f'{DOMAIN}/hardware/{h["slug"]}.html','description':h['official_support']},separators=(',',':'))
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{esc(h['name'])} compatibility for Ollama, LM Studio, Open WebUI, Hermes Agent, and OpenClaw, with official purchase links and dated evidence."><title>{esc(h['name'])} AI hardware compatibility | AIToolsEssentials</title><link rel="canonical" href="{DOMAIN}/hardware/{h['slug']}.html"><link rel="stylesheet" href="../css/styles.css"><link rel="stylesheet" href="../css/share.css"><script type="application/ld+json">{schema}</script></head><body><header class="global-nav"><a class="brand" href="../index.html">✦ AIToolsEssentials</a><nav class="nav-links"><a href="../tools/index.html">Tools</a><a href="../how-to/">How-to guides</a><a href="../change-radar/">Change radar</a><a href="../site-map/">Site map</a></nav><a class="nav-cta" href="../pricing/">Premium</a></header><main><section class="scene scene-dark"><div class="hardware-hero"><p class="kicker">Hardware compatibility · checked {esc(h['checked_at'])}</p><h1>{esc(h['name'])}</h1><p class="subhead">{esc(h['recommendation'])}</p><p class="hardware-badge">{esc(h['vendor'])} · {esc(h['type'])}</p></div></section><section class="scene scene-light"><div class="hardware-page"><div class="hardware-alert"><strong>Evidence boundary</strong><p>“Compatible” means the documented operating system/runtime path is plausible or official. It does not guarantee a particular model, speed, driver, thermals, or local inference quality. Always test the exact model and version before buying for a production workload.</p></div>{card('What the official source says',f'<p>{esc(h["official_support"])}</p>')} {card('Local-AI fit',f'<p>{esc(h["local_ai_fit"])}</p>')} {card('Specifications that matter',f'<ul class="hardware-specs">{specs}</ul>')} {card('Service compatibility matrix',f'<div class="table-wrap"><table><thead><tr><th>Service</th><th>Compatibility interpretation</th></tr></thead><tbody>{fit}</tbody></table></div>')} {card('Where to purchase',f'<p class="muted">These are official manufacturer or official marketplace links. Prices, regional availability, configurations, and delivery dates can change.</p><ul>{link_items(h["purchase_links"])}</ul>')} {card('Official evidence',f'<ul>{link_items(h["source_links"])}</ul>')} {card('Unresolved claims and re-checks',f'<ul>{unresolved}</ul>')}<p class="hardware-next"><a class="button button-blue" href="../hardware/">Back to hardware guide</a><a class="button button-dark" href="../decision-brief.html">Create a decision brief</a></p></div></section></main><footer class="footer"><span>© 2026 AIToolsEssentials</span><a href="../methodology/">Methodology</a><a href="../legal/privacy.html">Privacy</a><a href="../legal/terms.html">Terms</a></footer></body></html>'''

def generate(root:Path):
    hardware=json.loads((root/'data/hardware.json').read_text())
    out=root/'hardware'; out.mkdir(exist_ok=True)
    for h in hardware: (out/f'{h["slug"]}.html').write_text(detail(h))
    rows=''.join(f'<tr><td><strong><a href="{h["slug"]}.html">{esc(h["name"])}</a></strong><br><span class="muted">{esc(h["type"])}</span></td><td>{esc(h["recommendation"])}</td><td>{esc(h["memory"])}</td><td><a href="{h["slug"]}.html">View evidence →</a></td></tr>' for h in hardware)
    cards=''.join(f'<article class="content-hub-card"><span>{esc(h["vendor"])}</span><h2><a href="{h["slug"]}.html">{esc(h["name"])}</a></h2><p>{esc(h["recommendation"])}</p><a href="{h["slug"]}.html">Compatibility and purchase evidence →</a></article>' for h in hardware)
    hub=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Hardware compatibility and official purchase sources for Ollama, LM Studio, Open WebUI, Hermes Agent, and OpenClaw."><title>AI Hardware Compatibility &amp; Purchase Guide | AIToolsEssentials</title><link rel="canonical" href="{DOMAIN}/hardware/"><link rel="stylesheet" href="../css/styles.css"><link rel="stylesheet" href="../css/share.css"></head><body><header class="global-nav"><a class="brand" href="../index.html">✦ AIToolsEssentials</a><nav class="nav-links"><a href="../tools/index.html">Tools</a><a href="../how-to/">How-to guides</a><a href="../fit-interview/">Fit interview</a><a href="../change-radar/">Change radar</a></nav><a class="nav-cta" href="../pricing/">Premium</a></header><main><section class="scene scene-dark"><div class="hardware-hero"><p class="kicker">Local AI buying guide</p><h1>Choose hardware for the workload, not the sticker.</h1><p class="subhead">Compatibility, memory, thermals, model fit, and official purchase sources for local runtimes and agent gateways.</p><p class="hardware-badge">Last checked: 2026-08-26 · Manufacturer links only · no fabricated benchmarks</p><p><a class="button button-blue" href="/newsletter/" style="margin-left:8px">Keep/Cut Weekly</a></p></div></section><section class="scene scene-light"><div class="hardware-page"><div class="hardware-alert"><strong>Start with the architecture</strong><p>Ollama and LM Studio run models; Open WebUI provides a UI; Hermes Agent and OpenClaw orchestrate tools and channels. A gateway can run on a small low-power host while inference runs on a separate machine or cloud provider. Do not buy a GPU just to host a lightweight gateway.</p></div><div class="content-hub-grid">{cards}</div><section class="hardware-card"><h2>Cross-stack decision matrix</h2><div class="table-wrap"><table><thead><tr><th>Hardware</th><th>Best use</th><th>Memory guidance</th><th>Evidence</th></tr></thead><tbody>{rows}</tbody></table></div></section><section class="hardware-card"><h2>How to use this guide</h2><ol><li>Identify whether you need a gateway, local inference, or both.</li><li>Choose the exact model family and quantization before selecting RAM or VRAM.</li><li>Leave headroom for the operating system, context/KV cache, containers, browser automation, and concurrent services.</li><li>Check official runtime support for the OS, chip, driver, and version.</li><li>Buy only after testing a representative task or reserving a return path.</li></ol></section><p class="hardware-next"><a class="button button-blue" href="../how-to/install-ollama-and-run-a-model.html">Test Ollama locally</a><a class="button button-dark" href="../how-to/secure-a-self-hosted-ai-agent.html">Secure the stack</a></p></div></section></main><footer class="footer"><span>© 2026 AIToolsEssentials</span><a href="../methodology/">Methodology</a><a href="../legal/privacy.html">Privacy</a><a href="../legal/terms.html">Terms</a></footer></body></html>'''
    (out/'index.html').write_text(hub)
    return len(hardware)+1
if __name__=='__main__': print(generate(Path(__file__).resolve().parents[1]))
